    private List<Row> rows=new ArrayList<>();private int samples;private long lastWall,lastCpu=-1,lastRx=-1,lastTx=-1,processPss=-1,storageTotal,storageAvailable;private float cpu=Float.NaN,memory=Float.NaN,heap=Float.NaN,received=Float.NaN,sent=Float.NaN,storage=Float.NaN;
