        searchBar=new LinearLayout(getContext());searchBar.setGravity(Gravity.CENTER_VERTICAL);searchBar.setPadding(dp(5),dp(4),dp(9),dp(4));
        TextView hamburger=command("☰","Task Manager navigation",this::toggleNavigation);hamburger.setTextSize(21);searchBar.addView(hamburger,new LayoutParams(dp(44),dp(40)));
        search=new EditText(getContext());search.setSingleLine();search.setTextSize(13);search.setTypeface(Aero.face(getContext()));search.setFilters(new InputFilter[]{new InputFilter.LengthFilter(256)});search.setHint("Search by name, PID, or publisher");search.setContentDescription("Search Task Manager");search.setPadding(dp(12),0,dp(10),0);searchBar.addView(search,new LayoutParams(0,dp(36),1));addView(searchBar,new LayoutParams(-1,dp(48)));
        layout=new LinearLayout(getContext());nav=Aero.column(getContext());nav.setContentDescription("Task Manager sidebar");layout.addView(nav,new LayoutParams(dp(48),-1));main=Aero.column(getContext());header=Aero.column(getContext());body=Aero.column(getContext());main.addView(header,new LayoutParams(-1,-2));main.addView(body,new LayoutParams(-1,0,1));layout.addView(main,new LayoutParams(0,-1,1));addView(layout,new LayoutParams(-1,0,1));
        status=text("Waiting for a measured interval",10);status.setContentDescription("Task Manager update status");addView(status,new LayoutParams(-1,dp(25)));
        search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int n,int after){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int a,int before,int n){if(restoring)return;state.query=s.toString();renderBody(false);}});
        addOnLayoutChangeListener((v,l,t,r,b,ol,ot,or,ob)->{if(r-l!=width){width=r-l;render();}});appearance();
