    void appearance(){if(body==null)return;int key=Objects.hash(TenAppearance.dark(getContext()),TenStyle.accent(getContext()),store.prefs.getString("ten_font",""));if(key==palette&&body.getChildCount()>0)return;palette=key;TenAppearance.context(getContext());render();}
    private boolean dark(){return TenAppearance.dark(getContext());}private int ink(){return TenAppearance.ink(getContext());}private int muted(){return dark()?0xffc0c2ca:0xff5c5f68;}private int panel(){return dark()?0xff27282d:0xfffdfdff;}private int canvas(){return dark()?0xff202126:0xfff3f3f7;}
    private TextView text(String value,int size){TextView v=Aero.text(getContext(),value,size,ink());v.setPadding(dp(10),dp(5),dp(8),dp(5));return v;}
    private TextView command(String title,String description,Runnable action){TextView v=text(title,12);v.setGravity(Gravity.CENTER);v.setFocusable(true);v.setContentDescription(description);v.setMinHeight(dp(40));v.setBackground(TenStyle.appHover(getContext(),Color.TRANSPARENT));v.setOnClickListener(w->action.run());return v;}
    private void render(){stopAnimations();setBackgroundColor(canvas());searchBar.setBackgroundColor(canvas());search.setTextColor(ink());search.setHintTextColor(muted());search.setBackground(ElevenSurface.round(getContext(),dark()?0xff2b2c33:0xffffffff,5));main.setBackground(ElevenSurface.round(getContext(),panel(),6));status.setTextColor(muted());renderNavigation();renderHeader();renderBody(false);updateLabels();}
    private boolean expanded(){return width>=dp(560)&&(state.navigation==1||state.navigation<0&&width>=dp(760));}
    private void toggleNavigation(){if(width<dp(560)){dismissMenu();menu=new DesktopContextMenu(getContext(),"Task Manager navigation menu");for(String page:TaskManagerState.PAGES)menu.checked(page,state.page.equals(page),()->navigate(page));ContextMenus.centered(searchBar,(x,y)->ContextMenus.show(menu,searchBar,x,y));}else{state.navigation=expanded()?0:1;render();}}
    private void renderNavigation(){nav.removeAllViews();nav.getLayoutParams().width=dp(expanded()?188:48);ScrollView scroll=new ScrollView(getContext());scroll.setFillViewport(false);LinearLayout list=Aero.column(getContext());scroll.addView(list);nav.addView(scroll,new LayoutParams(-1,0,1));for(String page:TaskManagerState.PAGES)if(!page.equals("Settings"))navigationItem(list,page);navigationItem(nav,"Settings");}
    private void navigationItem(LinearLayout parent,String page){LinearLayout row=new LinearLayout(getContext());row.setGravity(Gravity.CENTER_VERTICAL);row.setFocusable(true);row.setContentDescription("Task Manager "+page);row.setTooltipText(page);boolean chosen=state.page.equals(page);row.setBackground(TenStyle.appHover(getContext(),chosen?(dark()?0xff34363d:0xffe4e5ec):Color.TRANSPARENT));View stripe=new View(getContext());stripe.setBackground(ElevenSurface.round(getContext(),chosen?TenAppearance.accent(getContext()):Color.TRANSPARENT,2));row.addView(stripe,new LayoutParams(dp(3),dp(18)));ElevenSymbols glyph=new ElevenSymbols(getContext(),page);LayoutParams g=new LayoutParams(dp(21),dp(21));g.setMargins(dp(10),0,dp(10),0);row.addView(glyph,g);if(expanded()){TextView label=text(page,12);label.setPadding(0,dp(3),dp(5),dp(3));label.setMaxLines(2);row.addView(label,new LayoutParams(0,-2,1));}row.setOnClickListener(v->navigate(page));LayoutParams lp=new LayoutParams(-1,dp(43));lp.setMargins(dp(2),dp(2),dp(3),dp(2));parent.addView(row,lp);}
    void navigate(String page){state.page=TaskManagerState.page(page);dismissMenu();render();}
    private void renderHeader(){header.removeAllViews();boolean wide=width-(expanded()?dp(188):dp(48))>=dp(540);TextView title=text(state.page,19);Aero.bold(title);title.setContentDescription("Task Manager page heading");LinearLayout top=new LinearLayout(getContext());top.setGravity(Gravity.CENTER_VERTICAL);if(wide){top.addView(title,new LayoutParams(0,dp(48),1));header.addView(top);}else header.addView(title,new LayoutParams(-1,dp(43)));HorizontalScrollView scroller=new HorizontalScrollView(getContext());scroller.setHorizontalScrollBarEnabled(false);LinearLayout commands=new LinearLayout(getContext());commands.setGravity(Gravity.CENTER_VERTICAL);scroller.addView(commands);commands.addView(command("＋  Run new task","Task Manager Run new task",host::newTask),new LayoutParams(dp(126),dp(42)));switchButton=command("Switch to","Task Manager Switch to",this::switchSelected);commands.addView(switchButton,new LayoutParams(dp(88),dp(42)));endButton=command("End task","Task Manager End task",this::endSelected);commands.addView(endButton,new LayoutParams(dp(104),dp(42)));commands.addView(command("⋯","Task Manager more options",this::more),new LayoutParams(dp(44),dp(42)));if(wide)top.addView(scroller,new LayoutParams(-2,dp(48)));else header.addView(scroller,new LayoutParams(-1,dp(42)));}
    private void renderBody(boolean preserve){JSONObject saved=preserve?ToolViewState.capture(body):null;stopAnimations();graphs.clear();live.clear();body.removeAllViews();rows.clear();switch(state.page){case "Processes":processes();break;case "Performance":performance();break;case "Details":details();break;case "App history":appHistory();break;case "Startup apps":startup();break;case "Users":users();break;case "Services":services();break;default:settings();}updateSelection();updateLabels();if(saved!=null)ToolViewState.restore(body,saved);TenAppearance.apply(main);}
    private boolean matches(String value){return value.toLowerCase(Locale.ROOT).contains(state.query.trim().toLowerCase(Locale.ROOT));}
    private List<Row> processRows(){List<Row> result=new ArrayList<>();ActivityManager manager=getContext().getSystemService(ActivityManager.class);List<ActivityManager.RunningAppProcessInfo> running=null;try{if(manager!=null)running=manager.getRunningAppProcesses();}catch(RuntimeException ignored){}if(running!=null)for(ActivityManager.RunningAppProcessInfo p:running){if(p.uid!=android.os.Process.myUid())continue;long bytes=-1;try{Debug.MemoryInfo[] info=manager.getProcessMemoryInfo(new int[]{p.pid});if(info.length>0)bytes=info[0].getTotalPss()*1024L;}catch(RuntimeException ignored){}result.add(new Row("pid:"+p.pid,p.processName,p.importance<=ActivityManager.RunningAppProcessInfo.IMPORTANCE_FOREGROUND?"Foreground":"Background",getContext().getPackageName(),p.pid,bytes,false,true));}if(result.stream().noneMatch(r->r.pid==android.os.Process.myPid()))result.add(new Row("pid:"+android.os.Process.myPid(),getContext().getPackageName(),"Nth process",getContext().getPackageName(),android.os.Process.myPid(),processPss,false,true));return result;}
    private List<Row> filtered(List<Row> input){List<Row> found=new ArrayList<>();for(Row row:input)if(matches(row.name+" "+row.status+" "+row.packageName+" "+(row.process?row.pid:"")+" "+(!row.external?"An Nth Experience":"")))found.add(row);found.sort((a,b)->{int order=state.sort.equals("Status")?a.status.compareToIgnoreCase(b.status):state.sort.equals("PID")?Integer.compare(a.pid,b.pid):state.sort.equals("Memory")?Long.compare(a.bytes,b.bytes):a.name.compareToIgnoreCase(b.name);if(state.sort.equals("CPU"))return TaskManagerState.compareMeasured(a.process&&a.pid==android.os.Process.myPid()?cpu:Double.NaN,b.process&&b.pid==android.os.Process.myPid()?cpu:Double.NaN,state.descending);if(state.sort.equals("Memory"))return TaskManagerState.compareMeasured(a.bytes<0?Double.NaN:a.bytes,b.bytes<0?Double.NaN:b.bytes,state.descending);return state.descending?-order:order;});return found;}
    private void processes(){LinearLayout table=table(new String[]{"Name","Status",percent(cpu)+"\nNth CPU",percent(memory)+"\nMemory","Disk","Network"},new int[]{220,105,88,98,80,90});List<Row> apps=new ArrayList<>(),external=new ArrayList<>();for(Task task:host.tasks()){String pkg=task.external?"":getContext().getPackageName();ComponentName component=ComponentName.unflattenFromString(task.id);if(component!=null)pkg=component.getPackageName();Row row=new Row(task.id,task.title,task.status,pkg,-1,-1,task.external,false);(task.external?external:apps).add(row);}group(table,"Apps",filtered(apps),false);group(table,"Recently opened Android apps",filtered(external),false);group(table,"Nth processes",filtered(processRows()),false);scope(body,"Nth windows share this launcher's process. Separate window CPU, disk and network counters are unavailable. Android app entries show recent activity; App info opens Android's controls.");}
    private LinearLayout table(String[] columns,int[] widths){HorizontalScrollView horizontal=new HorizontalScrollView(getContext());horizontal.setContentDescription("Task Manager table horizontal scroll");LinearLayout table=Aero.column(getContext());int width=0;for(int w:widths)width+=dp(w);horizontal.addView(table,new LayoutParams(width,-1));ScrollView vertical=new ScrollView(getContext());vertical.setFillViewport(true);vertical.setContentDescription("Task Manager table rows");vertical.addView(horizontal,new LayoutParams(-1,-1));body.addView(vertical,new LayoutParams(-1,0,1));LinearLayout heading=new LinearLayout(getContext());heading.setBackgroundColor(dark()?0xff30323a:0xfff1f2f7);for(int i=0;i<columns.length;i++){String name=columns[i];TextView cell=text(name,11);cell.setGravity(i==0?Gravity.START|Gravity.CENTER_VERTICAL:Gravity.END|Gravity.CENTER_VERTICAL);if(i<4){String key=i==0?"Name":i==1?"Status":i==2?(state.page.equals("Details")?"PID":"CPU"):"Memory";cell.setContentDescription("Task Manager sort by "+key);cell.setFocusable(true);cell.setOnClickListener(v->{state.descending=state.sort.equals(key)&&!state.descending;state.sort=key;renderBody(true);});}heading.addView(cell,new LayoutParams(dp(widths[i]),dp(53)));}table.addView(heading);table.setTag(widths);return table;}
    private void group(LinearLayout table,String title,List<Row> group,boolean detailRows){TextView label=text(title+" ("+group.size()+")",13);label.setTextColor(TenAppearance.accent(getContext()));table.addView(label,new LayoutParams(-1,dp(35)));for(Row row:group){rows.add(row);LinearLayout line=new LinearLayout(getContext());line.setGravity(Gravity.CENTER_VERTICAL);line.setFocusable(true);line.setContentDescription((row.process?"Process: ":"Task: ")+row.name);line.setSelected(row.id.equals(state.selected));line.setBackground(TenStyle.appHover(getContext(),row.id.equals(state.selected)?(dark()?0xff3a424d:0xffdcebf8):Color.TRANSPARENT));int[] widths=(int[])table.getTag();LinearLayout name=new LinearLayout(getContext());name.setGravity(Gravity.CENTER_VERTICAL);View image=row.process?new AeroIcon(getContext(),"taskmanager"):host.icon(row.id);name.addView(image,new LayoutParams(dp(21),dp(21)));TextView text=text(row.name,12);text.setSingleLine();text.setEllipsize(TextUtils.TruncateAt.END);name.addView(text,new LayoutParams(0,dp(43),1));name.setPadding(dp(9),0,0,0);line.addView(name,new LayoutParams(dp(widths[0]),dp(43)));String[] values=detailRows?new String[]{row.status,Integer.toString(row.pid),row.bytes>=0?bytes(row.bytes):"Unavailable",row.pid==android.os.Process.myPid()?percent(cpu):"—",Integer.toString(android.os.Process.myUid())}:new String[]{row.status,row.process&&row.pid==android.os.Process.myPid()?percent(cpu):"—",row.bytes>=0?bytes(row.bytes):"—","—","—"};for(int i=0;i<values.length;i++){TextView cell=text(values[i],11);cell.setGravity(Gravity.END|Gravity.CENTER_VERTICAL);cell.setMaxLines(2);if(!values[i].equals("—")&&(!detailRows&&(i==1||i==2)||detailRows&&(i==2||i==3))){float amount=i==2?(row.bytes>=0&&memoryInfo.totalMem>0?100f*row.bytes/memoryInfo.totalMem:Float.NaN):cpu;int color=TenStyle.mix(panel(),TenAppearance.accent(getContext()),.06f+Math.min(1,Math.max(0,Float.isNaN(amount)?0:amount/100))*.2f);cell.setBackgroundColor(color);}line.addView(cell,new LayoutParams(dp(widths[i+1]),dp(43)));}line.setOnClickListener(v->{state.selected=row.id;renderBody(true);});ContextMenus.bind(line,(x,y)->{state.selected=row.id;updateSelection();rowMenu(line,row,x,y);});table.addView(line);}if(group.isEmpty())table.addView(text(state.query.isEmpty()?"No entries in this group":"No matching entries",11));}
    private void details(){LinearLayout table=table(new String[]{"Name","Status","PID","Memory (PSS)","Nth CPU","UID"},new int[]{220,100,80,110,90,90});group(table,"Processes owned by Nth",filtered(processRows()),true);scope(body,"Only this app's UID is available. PSS is measured process memory; CPU is Nth's share of the available processor capacity.");}
    private Row selected(){for(Row row:rows)if(row.id.equals(state.selected))return row;return null;}
    private void updateSelection(){if(endButton==null)return;Row row=selected();boolean table=state.page.equals("Processes")||state.page.equals("Details");switchButton.setVisibility(state.page.equals("Processes")?VISIBLE:GONE);switchButton.setEnabled(table&&row!=null&&!row.process);switchButton.setAlpha(switchButton.isEnabled()?1:.4f);endButton.setVisibility(table?VISIBLE:GONE);endButton.setEnabled(table&&row!=null);endButton.setAlpha(endButton.isEnabled()?1:.4f);endButton.setText(row!=null&&row.external?"App info":row!=null&&row.process?"Restart Nth":"End task");}
    private void switchSelected(){Row row=selected();if(row!=null&&!row.process)host.switchTo(row.id);}
    private void endSelected(){Row row=selected();if(row==null)return;if(row.external)host.appInfo(row.id);else if(row.process)confirmRestart();else host.end(row.id);refresh();}
    private void confirmRestart(){Aero.dialog(getContext()).setTitle("Restart Nth Desktop?").setMessage("Refresh this launcher and restore its saved window session. Other Android apps are managed by Android.").setPositiveButton("Restart",(d,w)->host.restart()).setNegativeButton("Cancel",null).show();}
    private void rowMenu(View anchor,Row row,float x,float y){dismissMenu();menu=new DesktopContextMenu(getContext(),"Task Manager task commands");if(!row.process)menu.item("Switch to","programs",this::switchSelected);menu.item(row.external?"Open Android app info":row.process?"Restart Nth Desktop…":"End task",row.external?"settings":"close",this::endSelected);if(row.process)menu.item("Go to details","documentfile",()->navigate("Details"));ContextMenus.show(menu,anchor,x,y);}

    private void performance(){boolean wide=width-(expanded()?dp(188):dp(48))>=dp(540);LinearLayout container=new LinearLayout(getContext());container.setOrientation(wide?HORIZONTAL:VERTICAL);body.addView(container,new LayoutParams(-1,-1));LinearLayout choices=Aero.column(getContext());choices.setOrientation(wide?VERTICAL:HORIZONTAL);if(wide){ScrollView scroll=new ScrollView(getContext());scroll.addView(choices);container.addView(scroll,new LayoutParams(dp(165),-1));}else{HorizontalScrollView scroll=new HorizontalScrollView(getContext());scroll.setHorizontalScrollBarEnabled(false);scroll.addView(choices);container.addView(scroll,new LayoutParams(-1,dp(72)));}for(String resource:TaskManagerState.RESOURCES){LinearLayout tile=new LinearLayout(getContext());tile.setGravity(Gravity.CENTER_VERTICAL);tile.setPadding(dp(5),dp(4),dp(5),dp(4));tile.setContentDescription("Task Manager resource "+resource);tile.setFocusable(true);tile.setSelected(state.resource.equals(resource));tile.setBackground(TenStyle.appHover(getContext(),state.resource.equals(resource)?(dark()?0xff373a44:0xffe7e9f2):Color.TRANSPARENT));HistoryGraph mini=new HistoryGraph(getContext(),series(resource),resource.equals("Network")?history[4]:null,resource.equals("Network")?0:100,color(resource));mini.setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);graphs.add(mini);tile.addView(mini,new LayoutParams(dp(42),dp(30)));LinearLayout labels=Aero.column(getContext());TextView title=text(resource,12),value=text("",10);title.setPadding(dp(6),0,0,0);value.setPadding(dp(6),0,0,0);live.put("tile:"+resource,value);labels.addView(title);labels.addView(value);tile.addView(labels,new LayoutParams(0,-2,1));tile.setOnClickListener(v->{state.resource=resource;renderBody(false);});choices.addView(tile,new LayoutParams(wide?-1:dp(144),dp(64)));}
        ScrollView scroll=new ScrollView(getContext());LinearLayout detail=Aero.column(getContext());detail.setPadding(dp(12),dp(6),dp(12),dp(10));scroll.addView(detail);container.addView(scroll,wide?new LayoutParams(0,-1,1):new LayoutParams(-1,0,1));TextView title=text(state.resource,23);Aero.bold(title);detail.addView(title);note(detail,state.resource.equals("CPU")?"Nth Desktop Eleven · "+cores+" available logical processors":state.resource.equals("Memory")?"Device physical memory":state.resource.equals("Storage")?"Internal storage capacity":state.resource.equals("Java heap")?"Nth Java managed memory":"Device-wide interface traffic");
        LinearLayout axes=new LinearLayout(getContext());TextView scope=text(state.resource.equals("CPU")?"Nth CPU utilization":state.resource.equals("Storage")?"Capacity used":state.resource.equals("Network")?"Throughput":"Used",11),maximum=text(state.resource.equals("Network")?"Automatic scale":"100%",11);axes.addView(scope,new LayoutParams(0,-2,1));axes.addView(maximum);detail.addView(axes);HistoryGraph graph=new HistoryGraph(getContext(),series(state.resource),state.resource.equals("Network")?history[4]:null,state.resource.equals("Network")?0:100,color(state.resource));graph.setContentDescription(graphDescription());graphs.add(graph);detail.addView(graph,new LayoutParams(-1,Math.max(dp(96),Math.min(dp(174),getHeight()-dp(wide?165:270)))));TextView timing=text("Latest "+LENGTH+" measured samples · updates while active",10);detail.addView(timing);TextView metrics=text("",14);metrics.setContentDescription("Task Manager resource readings");live.put("resource",metrics);detail.addView(metrics);note(detail,state.resource.equals("CPU")?"CPU measures this Nth process across available cores. Android does not expose a reliable phone-wide CPU or GPU usage counter to this launcher.":state.resource.equals("Storage")?"This graph measures used capacity, not disk I/O activity. Android manages other apps' storage and device cleanup.":state.resource.equals("Network")?"Receive and send are measured from device interface counters. VPN interfaces may be counted more than once. This does not inspect connections or browsing content.":state.resource.equals("Java heap")?"Java heap is this app's managed memory. It is not total process or device memory.":"Device RAM includes Android and other apps. Process PSS is shown separately in Details.");}
    private String graphDescription(){return state.resource.equals("CPU")?"Nth Desktop CPU history":state.resource.equals("Memory")?"Device physical memory history":state.resource.equals("Network")?"Device received and sent traffic history":state.resource.equals("Storage")?"Device used storage capacity history":"Nth Java heap history";}
    private float[] series(String resource){return history[resource.equals("CPU")?0:resource.equals("Memory")?1:resource.equals("Java heap")?2:resource.equals("Network")?3:5];}
    private int color(String resource){int base=resource.equals("Memory")?0xffb180d7:resource.equals("Network")?0xffb88b5c:resource.equals("Storage")?0xff64a96d:resource.equals("Java heap")?0xffd29362:0xff57a4d3;return dark()?base:TenAccent.readableOn(base,0xfffcfdff);}
    private void updateLabels(){for(String resource:TaskManagerState.RESOURCES){TextView tile=live.get("tile:"+resource);if(tile!=null)tile.setText(resource.equals("CPU")?percent(cpu):resource.equals("Memory")?percent(memory):resource.equals("Storage")?percent(storage):resource.equals("Java heap")?percent(heap):rate(received)+" ↓");}TextView reading=live.get("resource");if(reading!=null){Runtime rt=Runtime.getRuntime();reading.setText(state.resource.equals("CPU")?"Utilization   "+percent(cpu)+"\nProcess CPU time   "+android.os.Process.getElapsedCpuTime()/1000+" s\nAvailable logical processors   "+cores+"\nProcess ID   "+android.os.Process.myPid():state.resource.equals("Memory")?"In use   "+bytes(memoryInfo.totalMem-memoryInfo.availMem)+"\nAvailable   "+bytes(memoryInfo.availMem)+"\nTotal physical memory   "+bytes(memoryInfo.totalMem):state.resource.equals("Storage")?"Used   "+bytes(storageTotal-storageAvailable)+"\nAvailable   "+bytes(storageAvailable)+"\nCapacity   "+bytes(storageTotal):state.resource.equals("Java heap")?"Used   "+bytes(rt.totalMemory()-rt.freeMemory())+"\nAllocated   "+bytes(rt.totalMemory())+"\nMaximum   "+bytes(rt.maxMemory()):"Receive   "+rate(received)+"\nSend   "+rate(sent)+"\nTotal received   "+counter(TrafficStats.getTotalRxBytes())+"\nTotal sent   "+counter(TrafficStats.getTotalTxBytes()));}if(status!=null)status.setText((state.paused?"Updates paused":"Updates every "+state.interval/1000+" s")+"  ·  Nth CPU "+percent(cpu)+"  ·  Device RAM "+percent(memory));}
    private void scope(LinearLayout parent,String message){TextView link=command("About these readings  ⓘ","Task Manager data scope",()->Aero.dialog(getContext()).setTitle("About these readings").setMessage(message).setPositiveButton("OK",null).show());link.setTextColor(muted());link.setTextSize(10);link.setMinHeight(0);link.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);parent.addView(link,new LayoutParams(-1,dp(30)));}
    private void note(LinearLayout parent,String message){TextView note=text(message,11);note.setTextColor(muted());parent.addView(note,new LayoutParams(-1,-2));}
    private LinearLayout document(){ScrollView scroll=new ScrollView(getContext());scroll.setFillViewport(true);LinearLayout result=Aero.column(getContext());result.setPadding(dp(6),dp(6),dp(6),dp(10));scroll.addView(result);body.addView(scroll,new LayoutParams(-1,-1));return result;}
    private void action(LinearLayout parent,String label,Runnable action){TextView button=command(label,label,action);button.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);button.setBackground(ElevenSurface.round(getContext(),dark()?0xff34363e:0xffeef0f6,5));LayoutParams p=new LayoutParams(-1,-2);p.setMargins(dp(4),dp(4),dp(4),dp(4));parent.addView(button,p);}
    private void appHistory(){LinearLayout page=document();note(page,"Nth CPU time since this process started; Nth UID network totals since device boot");page.addView(text("CPU time   "+android.os.Process.getElapsedCpuTime()/1000+" s\nReceived by Nth UID   "+counter(TrafficStats.getUidRxBytes(android.os.Process.myUid()))+"\nSent by Nth UID   "+counter(TrafficStats.getUidTxBytes(android.os.Process.myUid())),14));note(page,"Other apps' CPU and network history is private. Foreground app time today is available only with Android Usage Access.");if(!ExternalTasks.permitted(getContext())){action(page,"Set up Usage Access",()->host.open("setting:taskbar-usage-welcome"));return;}try{Calendar today=Calendar.getInstance();today.set(Calendar.HOUR_OF_DAY,0);today.set(Calendar.MINUTE,0);today.set(Calendar.SECOND,0);today.set(Calendar.MILLISECOND,0);UsageStatsManager manager=getContext().getSystemService(UsageStatsManager.class);Map<String,UsageStats> usage=manager==null?Collections.emptyMap():manager.queryAndAggregateUsageStats(today.getTimeInMillis(),System.currentTimeMillis());List<UsageStats> data=new ArrayList<>(usage.values());data.sort((a,b)->Long.compare(b.getTotalTimeInForeground(),a.getTotalTimeInForeground()));int shown=0;for(UsageStats item:data){if(item.getTotalTimeInForeground()<=0||!matches(item.getPackageName()))continue;String name=item.getPackageName();try{name=getContext().getPackageManager().getApplicationLabel(getContext().getPackageManager().getApplicationInfo(name,0)).toString();}catch(Exception ignored){}page.addView(text(name+"\nForeground time today: "+item.getTotalTimeInForeground()/60000+" min",12));if(++shown>=50)break;}if(shown==0)note(page,"No matching foreground usage is available for today.");}catch(RuntimeException error){note(page,"Android usage history is currently unavailable.");}action(page,"Review Android Usage Access",()->host.open("setting:taskbar-usage-welcome"));}
    private void startup(){LinearLayout page=document();note(page,"Nth startup choices. Android manages launch and background permissions for other apps.");String[] modes={"First launch only","Once per phone reboot","Off"};action(page,"Startup presentation: "+modes[Math.max(0,Math.min(2,store.prefs.getInt("startup_mode",0)))],()->Aero.dialog(getContext()).setTitle("Startup presentation").setItems(modes,(d,n)->{store.prefs.edit().putInt("startup_mode",n).apply();renderBody(false);}).setNegativeButton("Cancel",null).show());toggle(page,"Play Nth startup chime","startup_sound",false);toggle(page,"Show Welcome Center at startup","welcome_on_start",false);action(page,"Open startup settings",()->host.open("ten-setting:startup-apps"));action(page,"Android app settings",()->host.open("setting:android:apps"));}
    private void users(){LinearLayout page=document();LinearLayout profile=new LinearLayout(getContext());profile.setGravity(Gravity.CENTER_VERTICAL);profile.addView(ProfilePortrait.view(getContext(),store),new LayoutParams(dp(44),dp(44)));profile.addView(text(store.prefs.getString("desktop_name","Nth Desktop Eleven")+"\nLocal Nth profile",14),new LayoutParams(0,-2,1));page.addView(profile);note(page,"Android UID "+android.os.Process.myUid()+" · Current Nth session");page.addView(text("Nth CPU   "+percent(cpu)+"\nNth process memory (PSS)   "+(processPss>=0?bytes(processPss):"Unavailable"),14));note(page,"Nth profiles and virtual desktops are not separate Android sign-ins. Other users' sessions and resource counters are managed by Android.");action(page,"Open account settings",()->host.open("ten-setting:accounts"));}
    private void services(){LinearLayout page=document();note(page,"Services owned by Nth Desktop");int count=0;try{ActivityManager manager=getContext().getSystemService(ActivityManager.class);List<ActivityManager.RunningServiceInfo> services=manager==null?null:manager.getRunningServices(64);if(services!=null)for(ActivityManager.RunningServiceInfo service:services){if(service.uid!=android.os.Process.myUid()||!matches(service.service.getClassName()+" "+service.pid))continue;count++;page.addView(text(service.service.getShortClassName()+"\nPID "+service.pid+" · "+(service.foreground?"Foreground":"Running / bound"),12));}}catch(RuntimeException error){note(page,"Service details are unavailable on this device.");}if(count==0)note(page,state.query.isEmpty()?"No Nth services are reported as running.":"No matching Nth services.");note(page,"Android controls service lifetimes and other apps' services. Windows services and start/stop controls do not apply to this device.");action(page,"Notification access settings",()->host.open("ten-setting:notification-access"));}
    private void settings(){LinearLayout page=document();action(page,"Default start page: "+store.prefs.getString("taskmanager_default_page","Processes"),()->choose("Default start page",TaskManagerState.PAGES,store.prefs.getString("taskmanager_default_page","Processes"),choice->{store.prefs.edit().putString("taskmanager_default_page",choice).apply();renderBody(false);}));action(page,"Real-time update speed: "+state.interval/1000+(state.interval==1000?" second":" seconds"),this::speed);toggle(page,"Animated graphs","taskmanager_animate",true);action(page,"App theme: "+store.prefs.getString("taskmanager_theme","System"),()->choose("Task Manager app theme",Arrays.asList("System","Light","Dark"),store.prefs.getString("taskmanager_theme","System"),choice->{store.prefs.edit().putString("taskmanager_theme",choice).apply();palette=0;appearance();}));note(page,"System follows Nth's app theme. Light and Dark affect this Task Manager content and its menus.");action(page,state.paused?"Resume updates":"Pause updates",()->{state.paused=!state.paused;sync();renderBody(false);});note(page,"Measured samples only. CPU is Nth's normalized process CPU, memory/storage are device capacity, network uses actual interface counters. Sampling and animations stop when hidden or backgrounded.");action(page,"Open Personalization colors",()->host.open("ten-setting:colors"));}
    private void toggle(LinearLayout page,String title,String key,boolean fallback){Switch value=new Switch(getContext());value.setText(title);value.setTextColor(ink());value.setTextSize(13);value.setMinHeight(dp(48));value.setTypeface(Aero.face(getContext()));value.setContentDescription(title);value.setChecked(store.prefs.getBoolean(key,fallback));value.setOnCheckedChangeListener((v,on)->{store.prefs.edit().putBoolean(key,on).apply();stopAnimations();});page.addView(value,new LayoutParams(-1,-2));}
    private void choose(String title,List<String> choices,String current,java.util.function.Consumer<String> selected){Aero.dialog(getContext()).setTitle(title).setSingleChoiceItems(choices.toArray(new String[0]),choices.indexOf(current),(d,n)->{d.dismiss();selected.accept(choices.get(n));}).setNegativeButton("Cancel",null).show();}
    private void speed(){choose("Real-time update speed",Arrays.asList("High · 1 second","Normal · 2 seconds","Low · 5 seconds"),state.interval==1000?"High · 1 second":state.interval==5000?"Low · 5 seconds":"Normal · 2 seconds",choice->{state.interval=choice.startsWith("High")?1000:choice.startsWith("Low")?5000:2000;store.prefs.edit().putInt("taskmanager_speed",state.interval).apply();sync();renderBody(false);});}
    private void more(){dismissMenu();menu=new DesktopContextMenu(getContext(),"Task Manager more options");menu.item("Refresh now","refresh",this::refresh);menu.checked("Pause updates",state.paused,()->{state.paused=!state.paused;sync();renderBody(false);});menu.item("Real-time update speed","clock",this::speed);menu.item("Settings","settings",()->navigate("Settings"));ContextMenus.centered(header,(x,y)->ContextMenus.show(menu,header,x,y));}
    void tasksChanged(){if(!state.paused&&state.page.equals("Processes")&&(menu==null||!menu.showing()))renderBody(true);}
    void refresh(){if(closed||!active||!isShown())return;sample();renderBody(true);}
    private void sample(){long now=SystemClock.elapsedRealtime(),elapsed=lastWall==0?0:now-lastWall,currentCpu=android.os.Process.getElapsedCpuTime(),rx=TrafficStats.getTotalRxBytes(),tx=TrafficStats.getTotalTxBytes();cpu=TaskManagerState.cpu(currentCpu,lastCpu,elapsed,cores);received=TaskManagerState.rate(rx,lastRx,elapsed);sent=TaskManagerState.rate(tx,lastTx,elapsed);lastWall=now;lastCpu=currentCpu;lastRx=rx;lastTx=tx;ActivityManager manager=getContext().getSystemService(ActivityManager.class);try{if(manager!=null)manager.getMemoryInfo(memoryInfo);}catch(RuntimeException ignored){}memory=memoryInfo.totalMem>0?100f*(memoryInfo.totalMem-memoryInfo.availMem)/memoryInfo.totalMem:Float.NaN;Runtime runtime=Runtime.getRuntime();heap=100f*(runtime.totalMemory()-runtime.freeMemory())/Math.max(1,runtime.maxMemory());try{StatFs disk=new StatFs(Environment.getExternalStorageDirectory().getPath());storageTotal=disk.getTotalBytes();storageAvailable=disk.getAvailableBytes();storage=storageTotal>0?100f*(storageTotal-storageAvailable)/storageTotal:Float.NaN;}catch(RuntimeException ignored){storage=Float.NaN;storageTotal=storageAvailable=0;}try{Debug.MemoryInfo info=new Debug.MemoryInfo();Debug.getMemoryInfo(info);processPss=info.getTotalPss()*1024L;}catch(RuntimeException ignored){processPss=-1;}float[] values={cpu,memory,heap,received,sent,storage};for(int i=0;i<history.length;i++){System.arraycopy(history[i],1,history[i],0,LENGTH-1);history[i][LENGTH-1]=values[i];}samples++;updateLabels();boolean animated=sampling()&&Aero.motion(getContext())&&store.prefs.getBoolean("taskmanager_animate",true);for(HistoryGraph graph:graphs)graph.changed(animated);}
    private boolean sampling(){return !closed&&active&&!state.paused&&isAttachedToWindow()&&isShown()&&getWindowVisibility()==VISIBLE;}
    private void sync(){removeCallbacks(tick);lastWall=0;lastCpu=lastRx=lastTx=-1;if(!sampling())stopAnimations();else post(tick);updateLabels();}
    void active(boolean value){active=value;if(!value)dismissMenu();appearance();sync();}
    int sampleCount(){return samples;}int animatedGraphCount(){int n=0;for(HistoryGraph graph:graphs)if(graph.animating())n++;return n;}
    JSONObject state(){return state.json();}
    void restore(JSONObject value){state.restore(value);restoring=true;search.setText(state.query);search.setSelection(search.length());restoring=false;render();sync();}
    void close(){closed=true;active=false;removeCallbacks(tick);stopAnimations();dismissMenu();}
    private void stopAnimations(){for(HistoryGraph graph:graphs)graph.stop();}private void dismissMenu(){if(menu!=null){menu.dismiss();menu=null;}}
    @Override public boolean dispatchKeyEvent(KeyEvent event){if(event.getAction()==KeyEvent.ACTION_DOWN&&event.isAltPressed()&&event.getKeyCode()==KeyEvent.KEYCODE_F){search.requestFocus();search.selectAll();return true;}if(event.getAction()==KeyEvent.ACTION_DOWN&&event.getKeyCode()==KeyEvent.KEYCODE_ESCAPE&&search.hasFocus()&&search.length()>0){search.setText("");return true;}return super.dispatchKeyEvent(event);}
    @Override protected void onAttachedToWindow(){super.onAttachedToWindow();closed=false;active=true;sync();}@Override protected void onVisibilityChanged(View view,int visibility){super.onVisibilityChanged(view,visibility);if(body!=null)sync();}@Override protected void onWindowVisibilityChanged(int visibility){super.onWindowVisibilityChanged(visibility);if(body!=null)sync();}@Override protected void onDetachedFromWindow(){removeCallbacks(tick);stopAnimations();dismissMenu();super.onDetachedFromWindow();}
    private String percent(float value){return Float.isFinite(value)?String.format(Locale.getDefault(),"%.1f%%",value):"—";}private String rate(float value){return Float.isFinite(value)?bytes((long)value)+"/s":"Unavailable";}private String counter(long value){return value<0?"Unavailable":bytes(value);}private String bytes(long value){return android.text.format.Formatter.formatShortFileSize(getContext(),Math.max(0,value));}private int dp(int value){return Aero.dp(getContext(),value);}
    private static final class HistoryGraph extends View {
        final float[] first,second;float[] before,previousSecond;float fraction=1,maximum;final int color;final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);ValueAnimator animator;
        HistoryGraph(Context context,float[] first,float[] second,float maximum,int color){super(context);this.first=first;this.second=second;this.maximum=maximum;this.color=color;before=first.clone();previousSecond=second==null?null:second.clone();}
        void changed(boolean animate){stop();if(animate){fraction=0;animator=ValueAnimator.ofFloat(0,1);animator.setDuration(450);animator.addUpdateListener(a->{fraction=(float)a.getAnimatedValue();invalidate();});animator.start();}else{before=first.clone();if(second!=null)previousSecond=second.clone();invalidate();}}
        boolean animating(){return animator!=null&&animator.isRunning();}void stop(){if(animator!=null){animator.cancel();animator=null;}fraction=1;}
        @Override protected void onDraw(Canvas canvas){boolean dark=TenAppearance.dark(getContext());canvas.drawColor(dark?0xff24262d:0xfffcfdff);paint.setColor(dark?0xff424650:0xffdce5ec);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(1);for(int i=0;i<=12;i++)canvas.drawLine(i*getWidth()/12f,0,i*getWidth()/12f,getHeight(),paint);for(int i=0;i<=5;i++)canvas.drawLine(0,i*getHeight()/5f,getWidth(),i*getHeight()/5f,paint);float top=maximum;if(top<=0){top=1024;for(float n:first)if(Float.isFinite(n))top=Math.max(top,n*1.1f);if(second!=null)for(float n:second)if(Float.isFinite(n))top=Math.max(top,n*1.1f);}drawSeries(canvas,first,before,top,color,false);if(second!=null)drawSeries(canvas,second,previousSecond,top,dark?0xffe7c295:0xff805221,true);if(fraction>=1){before=first.clone();if(second!=null)previousSecond=second.clone();}}
        private void drawSeries(Canvas canvas,float[] data,float[] old,float ceiling,int tint,boolean dashed){paint.setColor(tint);paint.setStrokeWidth(Aero.dp(getContext(),1));paint.setPathEffect(dashed?new DashPathEffect(new float[]{5,4},0):null);for(int i=1;i<data.length;i++){float a=value(data,old,i-1),b=value(data,old,i);if(Float.isFinite(a)&&Float.isFinite(b))canvas.drawLine((i-1)*getWidth()/(data.length-1f),getHeight()*(1-Math.max(0,Math.min(1,a/ceiling))),i*getWidth()/(data.length-1f),getHeight()*(1-Math.max(0,Math.min(1,b/ceiling))),paint);}paint.setPathEffect(null);}
        private float value(float[] data,float[] old,int i){return fraction<1&&Float.isFinite(data[i])&&Float.isFinite(old[i])?old[i]+(data[i]-old[i])*fraction:data[i];}
    }
